class Solution {
    public long maximumSubarraySum(int[] nums,int k){
        Map<Integer,Long> minimumPrefix=new HashMap<>();
        long prefix=0,answer=Long.MIN_VALUE;
        for(int value:nums){
            long endPrefix=prefix+value;
            Long first=minimumPrefix.get(value-k),second=minimumPrefix.get(value+k);
            if(first!=null)answer=Math.max(answer,endPrefix-first);
            if(second!=null)answer=Math.max(answer,endPrefix-second);
            minimumPrefix.merge(value,prefix,Math::min);
            prefix=endPrefix;
        }
        return answer==Long.MIN_VALUE?0:answer;
    }
}

code.kotlin:
class Solution {
    fun maximumSubarraySum(nums:IntArray,k:Int):Long{
        val minimumPrefix=HashMap<Int,Long>();
        var prefix=0L;
        var answer=Long.MIN_VALUE;
        for(value in nums){
            val endPrefix=prefix+value;
            minimumPrefix[value-k]?.let{
                answer=maxOf(answer,endPrefix-it)
            };
            minimumPrefix[value+k]?.let{
                answer=maxOf(answer,endPrefix-it)
            };
            minimumPrefix[value]=minOf(minimumPrefix[value]?:Long.MAX_VALUE,prefix);
            prefix=endPrefix
        };
        return if(answer==Long.MIN_VALUE)0 else answer
    }
}

